<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';require_business_portal_access();
require_once dirname(__DIR__,2).'/app/AccountVerificationDelivery.php';
header('Cache-Control: no-store');header('Referrer-Policy: no-referrer');
$error='';$verified=false;$sent=isset($_GET['enviado']);
if(isset($_GET['token'])){try{(new AccountEmailVerificationService(db()))->verify((string)$_GET['token']);$verified=true;}catch(Throwable $e){if(class_exists('PortalIncidents',false))PortalIncidents::technical($e,'verify_email');$error=$e instanceof PDOException?'No se pudo verificar el enlace. Inténtalo más tarde.':$e->getMessage();http_response_code(400);}}
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{csrf();if(!throttle('account_verification_ip',5,900))throw new RuntimeException('Demasiadas solicitudes. Espera quince minutos.');$email=strtolower(trim((string)($_POST['email']??'')));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Escribe un correo válido.');
 if(throttle('account_verification_email',3,900,$email)){$q=db()->prepare('SELECT id FROM accounts WHERE email=? AND status="pending_activation"');$q->execute([$email]);$id=$q->fetchColumn();if($id){try{AccountVerificationDelivery::send(db(),$config,(int)$id);}catch(Throwable){error_log('No se confirmó el reenvío de activación.');}}}$sent=true;
 }catch(Throwable $e){if(class_exists('PortalIncidents',false))PortalIncidents::technical($e,'verify_email');$error=$e->getMessage();http_response_code(400);}
}
require_once __DIR__.'/../_account-page.php';account_page(true);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Verifica tu correo | Explorando Lugares</title><link rel="stylesheet" href="/assets/style.css"><link rel="stylesheet" href="/assets/account-registration.css"><link rel="stylesheet" href="/assets/account-access.css?v=2"></head><body><?php require __DIR__.'/../_account-header.php';?><main class="wrap account-portal account-access"><a class="account-access-brand brand" href="/index.html"><img class="brand-logo" src="/assets/brand/explorando-lugares-logo-v2-transparent.png" alt="Explorando Lugares" width="82" height="82"><span>Explorando<b>Lugares</b></span></a><section class="account-portal-card"><h1><?= $verified?'Correo verificado':'Verifica tu correo electrónico' ?></h1><?php if($verified):?><p>Tu cuenta está activada. Ya puedes iniciar sesión.</p><a class="pill" href="/negocios/acceso/">Iniciar sesión</a><?php else:?><?php if($error):?><p class="notice" role="alert"><?=esc($error)?></p><?php endif?><?php if($sent):?><p role="status">Si existe una cuenta pendiente con ese correo, recibirás un enlace de activación. Revisa también correo no deseado.</p><?php endif?><p>Abre el enlace que enviamos a tu correo para activar la cuenta. El enlace vence en 24 horas. Tu cuenta todavía no permite iniciar sesión.</p><form method="post" class="registration-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><label>Correo electrónico<input type="email" name="email" autocomplete="email" maxlength="254" required></label><button class="pill" type="submit">Solicitar nuevo enlace</button></form><?php endif?></section></main></body></html>
